const items = $input.all(); 
const out = []; 
const normalizeName = (str) => str ? String(str).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase().replace(/[^A-Z0-9]/g, '') : ''; 
const formatUsd = (val) => '$' + val.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' USD'; 
const formatCup = (val) => '$' + val.toLocaleString('en-US', { maximumFractionDigits: 0 }) + ' CUP'; 

// Función estricta para sanear nombres prohibidos en Windows y evitar inyecciones
const sanitizeFileName = (str) => str ? String(str).replace(/["<>:/\\|?*]/g, '').replace(/\s+/g, ' ').trim() : '';

for (const item of items) { 
  const row = item.json; 
  let nombreOriginal = row['PRODUCTO'] ? String(row['PRODUCTO']).trim() : ''; 
  if (!nombreOriginal) continue; 

  // Saneamiento para el identificador de archivos
  const nombreSaneado = sanitizeFileName(nombreOriginal);
  // NO sobreescribimos row['PRODUCTO'] para no romper el Update de Google Sheets
  row['PRODUCTO'] = nombreOriginal;

  const actualUsd = parseFloat(row['ACTUAL USD']) || 0; 
  const actualCup = parseFloat(row['ACTUAL CUP']) || 0; 
  const maxUsd = parseFloat(row['MAX HIST USD']) || 0; 
  const maxCup = parseFloat(row['MAX HIST CUP']) || 0; 
  const hasDiscount = (maxUsd > actualUsd) && (maxCup > actualCup); 

  const tallas = []; 
  for(let i=1; i<=9; i++){ 
    const t = row['T'+i]; 
    if(t && String(t).trim() !== '') tallas.push(String(t).trim()); 
  } 
  const tallaStr = tallas.join(', '); 

  // Nos aseguramos de estandarizar la propiedad CATEGORÍA al inicio
  const categoria = (row['CATEGORÍA'] || row['CATEGORIA'] || 'GENERAL').toUpperCase().trim();

  out.push({ 
    json: { 
      ...row, 
      CATEGORÍA: categoria, 
      matchKey: normalizeName(nombreSaneado), 
      productId: nombreSaneado, 
      usdPrice: actualUsd, 
      cupPrice: actualCup, 
      usdFormatted: formatUsd(actualUsd), 
      cupFormatted: formatCup(actualCup), 
      hasDiscount: hasDiscount, 
      maxUsdFormatted: hasDiscount ? formatUsd(maxUsd) : null, 
      maxCupFormatted: hasDiscount ? formatCup(maxCup) : null, 
      diffUsdFormatted: hasDiscount ? formatUsd(maxUsd - actualUsd) : null, 
      diffCupFormatted: hasDiscount ? formatCup(maxCup - actualCup) : null, 
      talla: tallaStr 
    } 
  }); 
} 
return out;

const allItems = $input.all();
const filteredInventory = [];
const filesMap = {};

// 1. Clasificar todo lo que viene de las dos ramas
for (const item of allItems) {
  const j = item.json;
  const key = j.matchKey;
  if (!key) continue;

  if (j.driveFileId) {
    // Es un archivo real de Google Drive
    if (!filesMap[key]) filesMap[key] = [];
    filesMap[key].push(j);
  }
  if (j.PRODUCTO) {
    // Es una fila del Inventario Sheets
    filteredInventory.push(j);
  }
}

const output = [];
// 2. Cruzar inventario con archivos de Drive
const globals = $('⚙️ Variables Globales').first().json;
const BATCH_LIMIT = parseInt(globals.BATCH_LIMIT || 30, 10); // LÍMITE DE SEGURIDAD DESDE VARIABLES GLOBALES

// Contar el total de productos en cola con imagen
let totalEnCola = 0;
for (const p of filteredInventory) {
  const key = p.matchKey;
  if (filesMap[key] && filesMap[key].length > 0) {
    totalEnCola++;
  }
}

let processedCount = 0;
for (const p of filteredInventory) {
  const key = p.matchKey;
  const productImages = filesMap[key] || [];

  // Si no hay imágenes en Drive para este producto, lo saltamos
  if (productImages.length === 0) continue; 

  // Detener el procesamiento si alcanzamos el límite de productos en este ciclo
  if (processedCount >= BATCH_LIMIT) break;
  processedCount++;

  // Ordenar variantes (la principal primero)
  productImages.sort((a, b) => (a.preservedSuffix || '').length - (b.preservedSuffix || '').length);

  productImages.forEach((img, index) => {
    output.push({
      json: {
        ...p, // Datos de precio y nombre del Sheets
        ...img, // ID del archivo de Drive
        photoIndex: index + 1,
        totalPhotos: productImages.length,
        isGallery: productImages.length > 1,
        isFirstPhoto: index === 0,
        folderName: p.PRODUCTO,
        marca: 'yourbrand',
        queueStats: {
          totalEnCola: totalEnCola,
          procesadosEnEstaEjecucion: Math.min(totalEnCola, BATCH_LIMIT),
          pendientes: Math.max(0, totalEnCola - BATCH_LIMIT)
        }
      }
    });
  });
}

return output;

const folderMap = {
  'ACCESORIO': '1C4kNBOb1uqvoF_NgbdnTTRbIRNfvEM-k',
  'ACCESORIOS': '1C4kNBOb1uqvoF_NgbdnTTRbIRNfvEM-k',
  'CARTERA': '1Ise_g2Z9MariEGvEJ3aVhoURhUsbkd81',
  'CARTERAS': '1Ise_g2Z9MariEGvEJ3aVhoURhUsbkd81',
  'ROPA': '1ny8RNFZKmUhUHhLoDrPGmaBkBOwTUmmF',
  'ROPAS': '1ny8RNFZKmUhUHhLoDrPGmaBkBOwTUmmF',
  'TECNOLOGIA': '1Jx27be3RkfP7z4k4X1h5KoUfaIhfTttJ',
  'TECNOLOGIAS': '1Jx27be3RkfP7z4k4X1h5KoUfaIhfTttJ',
  'ZAPATO': '1ODtHuzk51PQzsQKRWHpadewSJy9aDSs3',
  'ZAPATOS': '1ODtHuzk51PQzsQKRWHpadewSJy9aDSs3'
};

const items = $input.all();
const out = [];

for (const item of items) {
  const json = item.json;

  // Extraemos la categoría directamente del dato original arrastrado desde el Excel
  const categoria = (json['CATEGORÍA'] || json['CATEGORIA'] || 'DESCONOCIDA').toUpperCase().trim();
  const folderId = folderMap[categoria];

  // Si la categoría del Excel no coincide con ninguna carpeta de destino, bloqueamos el flujo
  if (!folderId) {
    throw new Error(`ERROR CRÍTICO: La categoría "${categoria}" para el producto "${json.PRODUCTO || json.productId || 'Desconocido'}" no existe en tu mapa de destino de Google Drive. Por favor, asegúrate de que esté bien escrita en el Excel.`);
  }

  const { categoryRaw, ...cleanJson } = json;

  out.push({
    json: {
      ...cleanJson,
      CATEGORÍA: categoria,
      categoryFolderId: folderId
    },
     binary: item.binary
  });
}

return out;

const categories = $('📂 Listar Categorías (Drive)').all();
const categoryMap = {};
categories.forEach(c => {
  categoryMap[c.json.id] = c.json.name;
});

const sanitizeFileName = (str) => str ? String(str).replace(/["<>:/\\|?*]/g, '').replace(/\s+/g, ' ').trim() : '';

const out = [];
const seenBaseKeys = new Set();

for (const item of $input.all()) {
  const file = item.json;
  const fileName = file.name;
  if (!fileName) continue;

  const parentId = (file.parents && file.parents.length > 0) ? file.parents[0] : null;
  const categoryRaw = categoryMap[parentId] || 'General';

  let cleanFileName = fileName;
  if (cleanFileName.includes('/')) {
    cleanFileName = cleanFileName.split('/').pop();
  }
  if (cleanFileName.includes('\\')) {
    cleanFileName = cleanFileName.split('\\').pop();
  }

  // Saneamiento de comillas y caracteres prohibidos
  cleanFileName = sanitizeFileName(cleanFileName);

  // CORRECCIÓN QUIRÚRGICA: Limpiar la extensión respetando puntos internos (solo extensiones de imagen estándar)
  let baseWithoutExt = cleanFileName;
  const extMatch = cleanFileName.match(/\.(jpe?g|png|webp|gif|jfif|bmp)$/i);
  if (extMatch) {
    baseWithoutExt = cleanFileName.slice(0, extMatch.index);
  }

  // Normalizar para de-duplicar la misma imagen (p. ej. "vestido" y "vestido.jpg" son la misma)
  const baseKey = baseWithoutExt.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase().replace(/[^A-Z0-9]/g, '');
  if (seenBaseKeys.has(baseKey)) {
    console.log('Ignorando duplicado de imagen para la base:', baseWithoutExt);
    continue; // Salta esta imagen para no procesarla dos veces
  }
  seenBaseKeys.add(baseKey);

  let matchKeyRaw = baseWithoutExt;
  let isVariant = false;
  // Evitar falsos positivos como años ("1997") o capacidades ("20.000MAH" -> "20") al requerir delimitador de variante claro
  const suffixMatch = baseWithoutExt.match(/\s\([2-9]\)$/);
  if (suffixMatch) {
    isVariant = true;
    matchKeyRaw = baseWithoutExt.substring(0, suffixMatch.index).trim();
  }

  const fullMatchKey = baseWithoutExt.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase().replace(/[^A-Z0-9]/g, '');
  const matchKey = matchKeyRaw.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase().replace(/[^A-Z0-9]/g, '');

  out.push({
    json: {
      driveFileId: file.id,
      fileName: fileName,
      cleanFileName: cleanFileName,
      categoryRaw: categoryRaw,
      matchKey: matchKey,
      fullMatchKey: fullMatchKey,
      isVariant: isVariant,
      preservedSuffix: suffixMatch ? suffixMatch[0] : ''
    }
  });
}
return out;

const categories = $input.all();
const rootId = '1gxj5OtOGF-m98S_2sC2xnDTBu5zRTiUX';

// Extraemos los IDs de todas las subcarpetas encontradas
const ids = categories.map(c => "'" + c.json.id + "' in parents");

// Añadimos la carpeta raíz por si hay fotos sueltas ahí
ids.push("'" + rootId + "' in parents");

// Construimos una mega-query para Google Drive (soporta miles de caracteres)
const query = "(" + ids.join(" or ") + ") and mimeType contains 'image/' and trashed = false";

// Devolvemos 1 solo item para que el siguiente nodo de Drive se ejecute exactamente 1 vez
return [{
  json: {
    driveQuery: query
  }
}];

// 1. Filtrar filas vacías primero
const validItems = $input.all().filter(item => {
  const row = item.json;
  const name = row['PRODUCTO'] ? String(row['PRODUCTO']).trim() : '';
  return name.length > 0;
});

// 2. Procesar solo los ítems válidos
return validItems.map(item => {
  const row = item.json;
  const name = String(row['PRODUCTO']).trim();
  // Limpieza agresiva de caracteres y tildes para generar una llave exacta
  const matchKey = name.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase().replace(/[^A-Z0-9]/g, '');

  return { 
    json: { 
      ...row, 
      matchKey: matchKey,
      newUsd: parseFloat(String(row['N. USD'] || '0').replace(/[^0-9.]/g, '')) || 0,
      newCup: parseFloat(String(row['N. CUP'] || '0').replace(/[^0-9.]/g, '')) || 0
    } 
  };
});

// --- LÓGICA DE UNIFICACIÓN ROBUSTA (Referencias Absolutas) ---

// 1. Extraemos los datos por NOMBRE DE NODO para evitar colisión de cables (n8n bug)
const inventory = $('💱 Recalcular Precio CUP').all().map(i => i.json);

let sales = [];
try {
    sales = $('🧹 Limpiar Rebajas').all().map(i => i.json);
} catch (e) {
    // Si no hay rebajas, sales se queda vacío
}

// 2. Construcción del Mapa de Rebajas Manuales (VIP)
const salesMap = {};
for (const s of sales) { 
    if (s.matchKey && typeof s.matchKey === 'string' && s.matchKey.length > 0) {
        salesMap[s.matchKey] = s; 
    }
}

const formatUsd = (val) => {
    const num = parseFloat(val);
    if (isNaN(num)) return '$0.00 USD';
    return '$' + num.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' USD';
};

const formatCup = (val) => {
    const num = parseFloat(val);
    if (isNaN(num)) return '$0 CUP';
    return '$' + num.toLocaleString('en-US', { maximumFractionDigits: 0 }) + ' CUP';
};

// 3. Procesamiento del Inventario
return inventory.map(p => {
    // Verificación exacta en el mapa de rebajas manuales
    const sale = (p.matchKey && typeof p.matchKey === 'string') ? salesMap[p.matchKey] : null;

    // Lógica de Rebaja Natural (Historial)
    const actualCup = parseFloat(p['ACTUAL CUP']) || 0;
    const actualUsd = parseFloat(p['ACTUAL USD']) || 0;
    const maxCup = parseFloat(p['MAX HIST CUP']) || 0;
    const maxUsd = parseFloat(p['MAX HIST USD']) || 0;
    const isNaturalSale = (maxUsd > actualUsd) || (maxCup > actualCup);

    // RECONSTRUCCIÓN INMUTABLE DEL OBJETO
    let itemFinal = { ...p };

    if (sale) {
        // ES UNA REBAJA ESPECIAL (VERDE)
        itemFinal.specialSale = true;
        itemFinal.isSale = true;
        itemFinal.hasDiscount = true;

        // Sobreescribimos precios con los de la hoja de rebajas
        itemFinal.oldUsdPrice = itemFinal.oldUsdPrice || itemFinal.usdPrice || 0;
        itemFinal.oldCupPrice = itemFinal.oldCupPrice || itemFinal.cupPrice || 0;
        itemFinal.maxUsdFormatted = formatUsd(itemFinal.oldUsdPrice);
        itemFinal.maxCupFormatted = formatCup(itemFinal.oldCupPrice);

        itemFinal.usdPrice = sale.newUsd || 0;
        itemFinal.cupPrice = sale.newCup || 0;
        itemFinal.usdFormatted = formatUsd(itemFinal.usdPrice);
        itemFinal.cupFormatted = formatCup(itemFinal.cupPrice);

        const diffUsd = itemFinal.oldUsdPrice - itemFinal.usdPrice;
        const diffCup = itemFinal.oldCupPrice - itemFinal.cupPrice;
        itemFinal.diffUsdFormatted = diffUsd > 0 ? '-' + formatUsd(diffUsd) : null;
        itemFinal.diffCupFormatted = diffCup > 0 ? '-' + formatCup(diffCup) : null;
    } else {
        // NO ES REBAJA ESPECIAL (Normal o Roja)
        itemFinal.specialSale = false;
        itemFinal.isSale = isNaturalSale;
        itemFinal.hasDiscount = isNaturalSale;

        // Mantenemos precios originales
        itemFinal.oldUsdPrice = itemFinal.oldUsdPrice || itemFinal.usdPrice || 0;
        itemFinal.oldCupPrice = itemFinal.oldCupPrice || itemFinal.cupPrice || 0;

        if (!isNaturalSale) {
            itemFinal.diffUsdFormatted = null;
            itemFinal.diffCupFormatted = null;
        }
    }

    return { json: itemFinal };
});

const data = $('📂 Asignar Carpeta Destino').item.json;
const uploadData = $('☁️ Subir Foto Única (Drive)').item.json;
return [{
    json: { ...data, newDriveId: uploadData.id, webViewLink: uploadData.webViewLink },
    pairedItem: { item: 0 }
}];

const searchResults = $input.all();
const uploadItems = $('☁️ Subir Foto Única (Drive)').all();
const uploadIds = uploadItems.map(item => item.json.id);

const productId = $('📂 Asignar Carpeta Destino').item.json.productId.trim().toUpperCase();

const obsoleteFiles = [];

for (const file of searchResults) {
    const fileName = file.json.name;
    const fileId = file.json.id;

    if (!fileId || !fileName) continue;

    // Normalize file name: remove extension and variant suffixes like (2), _2, -2
    const normName = fileName.substring(0, fileName.lastIndexOf('.'))
        .replace(/\s*\(\d+\)\s*$/, '')
        .replace(/\s*-\s*\d+\s*$/, '')
        .replace(/\s*_\s*\d+\s*$/, '')
        .trim()
        .toUpperCase();

    // If it belongs to this product and is NOT one of our newly uploaded file IDs
    if (normName === productId && !uploadIds.includes(fileId)) {
        obsoleteFiles.push({
            json: { id: fileId, name: fileName },
            pairedItem: { item: 0 }
        });
    }
}

if (obsoleteFiles.length > 0) {
    return obsoleteFiles;
} else {
    // Always return at least 1 item to prevent loop blocking!
    return [{
        json: { skipDelete: true },
        pairedItem: { item: 0 }
    }];
}

